class Solution { public int evaluate(String expression){return eval(expression,new HashMap<>());}private int eval(String expression,Map<String,Integer> environment){if(expression.charAt(0)!='('){if(expression.charAt(0)=='-'||Character.isDigit(expression.charAt(0)))return Integer.parseInt(expression);return environment.get(expression);}List<String> tokens=split(expression.substring(1,expression.length()-1));if(tokens.get(0).equals("add"))return eval(tokens.get(1),environment)+eval(tokens.get(2),environment);if(tokens.get(0).equals("mult"))return eval(tokens.get(1),environment)*eval(tokens.get(2),environment);Map<String,Integer> local=new HashMap<>(environment);for(int i=1;i<tokens.size()-1;i+=2)local.put(tokens.get(i),eval(tokens.get(i+1),local));return eval(tokens.get(tokens.size()-1),local);}private List<String> split(String value){List<String> tokens=new ArrayList<>();int depth=0,start=0;for(int i=0;i<=value.length();i++){if(i==value.length()||value.charAt(i)==' '&&depth==0){tokens.add(value.substring(start,i));start=i+1;}else if(value.charAt(i)=='(')depth++;else if(value.charAt(i)==')')depth--;}return tokens;} }
